interface CompanyLogoProps {
  company: string;
  className?: string;
}

export default function CompanyLogo({ company, className = 'h-6' }: CompanyLogoProps) {
  const norm = company.toLowerCase();

  if (norm.includes('swiss re')) {
    return <SwissReLogo className={className} />;
  }
  if (norm.includes('inbev') || norm.includes('abinbev') || norm.includes('ab inbev')) {
    return <ABInBevLogo className={className} />;
  }
  if (norm === 'ey' || norm.includes('ernst')) {
    return <EYLogo className={className} />;
  }
  if (norm.includes('accenture')) {
    return <AccentureLogo className={className} />;
  }

  return (
    <span className="font-bold text-sm text-[#151514] dark:text-[#f4f0e8]">
      {company}
    </span>
  );
}
